24	## Add an instance of an IP or inline_hdl to the block design.
25	#
26	# \param[i_ip] - name of the IP
27	# \param[i_name] - name of the instance
28	# \param[i_params] - a list of the parameters, the list must contain {name, value}
29	# pairs
30	#
31	proc ad_ip_instance {i_ip i_name {i_params {}}} {
32	  set ip_type ip
33	  set ip_def [get_ipdefs -all -filter "VLNV =~ *:${i_ip}:* && \
34	    design_tool_contexts =~ *IPI* && UPGRADE_VERSIONS == \"\""]
35	  if {[string match "*inline_hdl*" $ip_def]} {
36	    set ip_type inline_hdl
37	  }
38	  set cell [create_bd_cell -type ${ip_type} -vlnv ${ip_def} ${i_name}]
39	  if {$i_params != {}} {
40	    set config {}
41	    # Add CONFIG. prefix to all config options
42	    foreach {k v} $i_params {
43	      lappend config "CONFIG.$k" $v
44	    }
45	    set_property -dict $config $cell
46	  }
47	}
