49	## Define a parameter value of an IP instance.
50	#
51	# \param[i_name] - name of the instance
52	# \param[i_param] - name of the parameter
53	# \param[i_value] - value of the parameter
54	#
55	proc ad_ip_parameter {i_name i_param i_value} {
56	
57	  set_property ${i_param} ${i_value} [get_bd_cells ${i_name}]
58	}
