60	## Define the type of an IPI interface object, in general these objects an be:
61	#  interface pins, ports or nets; or cells pins, ports or nets.
62	#
63	# \param[p_name] - name of the object
64	#
65	# \return - the type of the object
66	#
67	proc ad_connect_type {p_name} {
68	
69	  set m_name ""
70	
71	  if {$m_name eq ""} {set m_name [get_bd_intf_pins  -quiet $p_name]}
72	  if {$m_name eq ""} {set m_name [get_bd_pins       -quiet $p_name]}
73	  if {$m_name eq ""} {set m_name [get_bd_intf_ports -quiet $p_name]}
74	  if {$m_name eq ""} {set m_name [get_bd_ports      -quiet $p_name]}
75	  if {$m_name eq ""} {set m_name [get_bd_intf_nets  -quiet $p_name]}
76	  if {$m_name eq ""} {set m_name [get_bd_nets       -quiet $p_name]}
77	
78	  return $m_name
79	}
80	
81	## Get type of object, for internal use only!
82	proc ad_connect_int_class {p_name} {
83	
84	  set m_name ""
85	
86	  if {$m_name eq ""} {set m_name [get_bd_intf_pins  -quiet $p_name]}
87	  if {$m_name eq ""} {set m_name [get_bd_pins       -quiet $p_name]}
88	  # All ports can be handled as pins
89	  # if {$m_name eq ""} {set m_name [get_bd_intf_ports -quiet $p_name]}
90	  # if {$m_name eq ""} {set m_name [get_bd_ports      -quiet $p_name]}
91	  if {$m_name eq ""} {set m_name [get_bd_intf_nets  -quiet $p_name]}
92	  if {$m_name eq ""} {set m_name [get_bd_nets       -quiet $p_name]}
93	
94	  if {!($m_name eq "")} {
95	    return [get_property CLASS $m_name]
96	  }
97	
98	  if {$p_name eq "GND" || $p_name eq "VCC"} {
99	    return "const"
100	  }
101	
102	  return "newnet"
103	}
