105	## Get constant source, for internal use only!
106	proc ad_connect_int_get_const {name width} {
107	  switch $name {
108	    GND {
109	      set value 0
110	    }
111	    VCC {
112	      set value [expr (1 << $width) - 1]
113	    }
114	    default {
115	      error "ERROR: ad_connect_int_get_const: Unhandled constant name $name"
116	    }
117	  }
118	
119	  set cell_name "$name\_$width"
120	
121	  set cell [get_bd_cells -quiet $cell_name]
122	  if {$cell eq ""} {
123	    # Create new constant source
124	    ad_ip_instance ilconstant $cell_name
125	    set cell [get_bd_cells -quiet $cell_name]
126	    set_property CONFIG.CONST_WIDTH $width $cell
127	    set_property CONFIG.CONST_VAL $value $cell
128	  }
129	
130	  return $cell
131	}
