133	## Determine pin/port/net width, for internal use only!
134	proc ad_connect_int_width {obj} {
135	  if {$obj eq ""} {
136	    error "ERROR: ad_connect_int_width: No object provided."
137	  }
138	
139	  set classname [get_property -quiet CLASS $obj]
140	  if {$classname eq ""} {
141	    error "ERROR: ad_connect_int_width: Cannot determine width of class-less object: $obj"
142	  }
143	  if {[string first intf $classname] != -1} {
144	    error "ERROR: ad_connect_int_width: Cannot determine width of interface object: $obj ($classname)"
145	  }
146	
147	  if {([get_property -quiet LEFT $obj] eq "") || ([get_property -quiet RIGHT $obj] eq "")} {
148	    return 1
149	  }
150	
151	  set left [get_property LEFT $obj]
152	  set right [get_property RIGHT $obj]
153	
154	  set high [expr max($left,$right)]
155	  set low [expr min($left,$right)]
156	
157	  return [expr {1 + $high - $low}]
158	}
