161	## Connect two IPI interface object together.
162	#
163	# \param[p_name_1] - first object name
164	# \param[p_name_2] - second object name
165	#
166	# Valid object types are: GND/VCC, net/port/pin names or interface names
167	#
168	# \return - N/A
169	#
170	proc ad_connect {name_a name_b} {
171	  set type_a [ad_connect_int_class $name_a]
172	  set type_b [ad_connect_int_class $name_b]
173	
174	  set obj_a [ad_connect_type $name_a]
175	  set obj_b [ad_connect_type $name_b]
176	
177	  if {!([string first intf $type_a]+1) != !([string first intf $type_b]+1)} {
178	    error "ERROR: ad_connect: Cannot connect non-interface to interface: $name_a ($type_a) <-/-> $name_b ($type_b)"
179	  }
180	
181	  switch $type_a,$type_b {
182	    newnet,newnet {
183	      error "ERROR: ad_connect: Cannot create connection between two new nets: $name_a <-/-> $name_b"
184	    }
185	    const,const {
186	      error "ERROR: ad_connect: Cannot connect constant to constant: $name_a <-/-> $name_b"
187	    }
188	    bd_net,bd_net -
189	    bd_intf_net,bd_intf_net {
190	      error "ERROR: ad_connect: Cannot connect (intf) net to (intf) net: $name_a ($type_a) <-/-> $name_b ($type_b)"
191	    }
192	    bd_net,newnet -
193	    newnet,bd_net {
194	      error "ERROR: ad_connect: Cannot connect existing net to new net: $name_a ($type_a) <-/-> $name_b ($type_b)"
195	    }
196	    const,newnet -
197	    newnet,const {
198	      error "ERROR: ad_connect: Cannot connect new network to constant, instead you should connect to the constant directly: $name_a ($type_a) <-/-> $name_b ($type_b)"
199	    }
200	
201	    bd_pin,bd_pin {
202	      connect_bd_net $obj_a $obj_b
203	      puts "connect_bd_net $obj_a $obj_b"
204	      return
205	    }
206	    bd_net,bd_pin {
207	      connect_bd_net -net $obj_a $obj_b
208	      puts "connect_bd_net -net $obj_a $obj_b"
209	      return
210	    }
211	    bd_pin,bd_net {
212	      connect_bd_net -net $obj_b $obj_a
213	      puts "connect_bd_net -net $obj_b $obj_a"
214	      return
215	    }
216	    bd_pin,newnet {
217	      connect_bd_net -net $name_b $obj_a
218	      puts "connect_bd_net -net $name_b $obj_a"
219	      return
220	    }
221	    newnet,bd_pin {
222	      connect_bd_net -net $name_a $obj_b
223	      puts "connect_bd_net -net $name_a $obj_b"
224	      return
225	    }
226	    bd_intf_pin,bd_intf_pin {
227	      connect_bd_intf_net $obj_a $obj_b
228	      puts "connect_bd_intf_net $obj_a $obj_b"
229	      return
230	    }
231	    const,bd_pin -
232	    const,bd_net {
233	      # Handled after the switch statement
234	    }
235	    bd_net,const -
236	    bd_pin,const {
237	      # Swap vars
238	      set tmp $obj_a
239	      set obj_a $obj_b
240	      set obj_b $tmp
241	      set tmp $name_a
242	      set name_a $name_b
243	      set name_b $tmp
244	      # Handled after the switch statement
245	    }
246	    default {
247	      error "ERROR: ad_connect: Cannot connect, case unhandled: $name_a ($type_a) <-/-> $name_b ($type_b)"
248	    }
249	  }
250	
251	  # Continue working on nets that connect to constant. obj_b is the net/pin
252	  set width [ad_connect_int_width $obj_b]
253	  set cell [ad_connect_int_get_const $name_a $width]
254	  connect_bd_net [get_bd_pin $cell/dout] $obj_b
255	  puts "connect_bd_net [get_bd_pin $cell/dout] $obj_b"
256	}
