258	## Disconnect two IPI interface object together.
259	#
260	# \param[p_name_1] - first object name
261	# \param[p_name_2] - second object name
262	#
263	# Valid object types are: GND/VCC, net/port/pin names or interface names
264	#
265	# \return - N/A
266	#
267	proc ad_disconnect {p_name_1 p_name_2} {
268	
269	  set m_name_1 [ad_connect_type $p_name_1]
270	  set m_name_2 [ad_connect_type $p_name_2]
271	
272	  if {[get_property CLASS $m_name_1] eq "bd_net"} {
273	    disconnect_bd_net $m_name_1 $m_name_2
274	    return
275	  }
276	
277	  if {[get_property CLASS $m_name_1] eq "bd_port"} {
278	    delete_bd_objs -quiet [get_bd_nets -quiet -of_objects \
279	      [find_bd_objs -relation connected_to $m_name_1]]
280	    delete_bd_objs -quiet $m_name_1
281	    return
282	  }
283	
284	  if {[get_property CLASS $m_name_1] eq "bd_pin"} {
285	    delete_bd_objs -quiet [get_bd_nets -quiet -of_objects \
286	      [find_bd_objs -relation connected_to $m_name_1]]
287	    delete_bd_objs -quiet $m_name_1
288	    return
289	  }
290	
291	  if {[get_property CLASS $m_name_1] eq "bd_intf_pin"} {
292	    delete_bd_objs -quiet [get_bd_intf_nets -of_objects [get_bd_intf_ports $m_name_1]]
293	    delete_bd_objs -quiet [get_bd_intf_ports $m_name_1]
294	    return
295	  }
296	}
