298	## Define all the connections between the transceiver IP, the transceiver
299	#  configuration IP and the JESD204 Link IP.
300	#
301	#  \param[u_xcvr] - name of the transceiver IP (util_adxcvr)
302	#  \param[a_xcvr] - name of the transceiver configuration IP (axi_adxcvr)
303	#  \param[a_jesd] - name of the JESD204 link IP
304	#  \param[lane_map] - lane_map maps the logical lane $n onto the physical lane
305	#  $lane_map[$n], otherwise logical lane $n is mapped onto physical lane $n.
306	#  \param[link_clk] - define a custom link clock, should be a net name
307	#  connected to the clock source. If not used, the rx|tx_clk_out_0 is used as
308	#  link clock. This should be lane rate / (encoder_ratio*datapath width in bits)
309	#  where encoder_ratio is 10/8 for 8b10b encoding or 66/64 for 64b66b link layer.
310	#  \param[device_clk] - define a custom device clock, should be a net name
311	#  connected to the clock source. If not used, the link_clk is used as
312	#  device clock
313	#  \param[num_of_max_lanes] - maximum number of used lanes at physical layer per link,
314	#  this parameter is used only when the project is parameterized in order to connect the unused lanes
315	#  to the util_adxcvr block. If not used, the number of connected lanes will be defined
316	#  by the axi_adxcvr.
317	#
318	
319	proc ad_xcvrcon {u_xcvr a_xcvr a_jesd {lane_map {}} {link_clk {}} {device_clk {}} {num_of_max_lanes -1} {partial_lane_map {}} {connect_empty_lanes 1}} {
320	
321	  global xcvr_index
322	  global xcvr_tx_index
323	  global xcvr_rx_index
324	  global xcvr_instance
325	
326	  set qpll_enable [get_property CONFIG.QPLL_ENABLE [get_bd_cells $a_xcvr]]
327	  set tx_or_rx_n [get_property CONFIG.TX_OR_RX_N [get_bd_cells $a_xcvr]]
328	
329	  set xcvr_type [get_property CONFIG.XCVR_TYPE [get_bd_cells $u_xcvr]]
330	
331	  set link_mode_u [get_property CONFIG.LINK_MODE [get_bd_cells $u_xcvr]]
332	  set link_mode_a [get_property CONFIG.LINK_MODE [get_bd_cells $a_xcvr]]
333	
334	  if {$link_mode_u != $link_mode_a} {
335	     puts "CRITICAL WARNING: LINK_MODE parameter mismatch between $u_xcvr ($link_mode_u) and $a_xcvr ($link_mode_a)"
336	  }
337	  set link_mode $link_mode_u
338	
339	  set jesd204_bd_type [get_property TYPE [get_bd_cells $a_jesd]]
340	
341	  if {$jesd204_bd_type == "hier"} {
342	    set jesd204_type 0
343	  } else {
344	    set jesd204_type 1
345	  }
346	
347	  if {$xcvr_instance ne $u_xcvr} {
348	    set xcvr_index [expr ($xcvr_index + 1)]
349	    set xcvr_tx_index 0
350	    set xcvr_rx_index 0
351	    set xcvr_instance $u_xcvr
352	  }
353	
354	  set txrx "rx"
355	  set data_dir "I"
356	  set ctrl_dir "O"
357	  set index $xcvr_rx_index
358	
359	  if {$tx_or_rx_n == 1} {
360	
361	    set txrx "tx"
362	    set data_dir "O"
363	    set ctrl_dir "I"
364	    set index $xcvr_tx_index
365	  }
366	
367	  set m_sysref ${txrx}_sysref_${index}
368	  set m_sync ${txrx}_sync_${index}
369	  set m_data ${txrx}_data
370	
371	  if {$xcvr_index >= 1} {
372	
373	    set m_sysref ${txrx}_sysref_${xcvr_index}_${index}
374	    set m_sync ${txrx}_sync_${xcvr_index}_${index}
375	    set m_data ${txrx}_data_${xcvr_index}
376	  }
377	
378	  if {$jesd204_type == 0} {
379	    set num_of_links [get_property CONFIG.NUM_LINKS [get_bd_cells $a_jesd/$txrx]]
380	  } else {
381	    set num_of_links 1
382	  }
383	
384	  set no_of_lanes [get_property CONFIG.NUM_LANES [get_bd_cells $a_jesd/$txrx]]
385	  set max_no_of_lanes $no_of_lanes
386	
387	  if {$num_of_max_lanes != -1} {
388	    set max_no_of_lanes $num_of_max_lanes
389	  }
390	  create_bd_port -dir I $m_sysref
391	  create_bd_port -from [expr $num_of_links - 1] -to 0 -dir ${ctrl_dir} $m_sync
392	
393	  set use_2x_clk 0
394	  if {$link_clk == {}} {
395	    # For 204C modes on GTH a 2x clock is required to drive the PCS
396	    # In such case set the xcvr out clock to be the double of the lane rate/66(40)
397	    # and use the secondary div2 clock output for the link clock
398	    if {$link_mode == 2 && ($xcvr_type == 5 || $xcvr_type == 8)} {
399	      set link_clk ${u_xcvr}/${txrx}_out_clk_div2_${index}
400	      set link_clk_2x ${u_xcvr}/${txrx}_out_clk_${index}
401	      set use_2x_clk 1
402	    } else {
403	      if {$partial_lane_map != {}} {
404	        set cur_index [lindex $partial_lane_map $index]
405	        set link_clk ${u_xcvr}/${txrx}_out_clk_${cur_index}
406	      } else {
407	        set link_clk ${u_xcvr}/${txrx}_out_clk_${index}
408	      }
409	    }
410	    set rst_gen [regsub -all "/" ${a_jesd}_rstgen "_"]
411	    set create_rst_gen 1
412	  } else {
413	    set rst_gen ${link_clk}_rstgen
414	    # Only create one reset gen per clock
415	    set create_rst_gen [expr {[get_bd_cells -quiet ${rst_gen}] == {}}]
416	  }
417	
418	  if {$device_clk == {}} {
419	    set device_clk $link_clk
420	  } else {
421	    set rst_gen ${device_clk}_rstgen
422	    # Only create one reset gen per clock
423	    set create_rst_gen [expr {[get_bd_cells -quiet ${rst_gen}] == {}}]
424	  }
425	
426	  if {${create_rst_gen}} {
427	    ad_ip_instance proc_sys_reset ${rst_gen}
428	    ad_connect ${device_clk} ${rst_gen}/slowest_sync_clk
429	    ad_connect sys_cpu_resetn ${rst_gen}/ext_reset_in
430	  }
431	
432	  if {$partial_lane_map != {}} {
433	    for {set n 0} {$n < $no_of_lanes} {incr n} {
434	
435	      set phys_lane [lindex $partial_lane_map $n]
436	
437	      if {$phys_lane != {}} {
438	        if {$jesd204_type == 0} {
439	          ad_connect  ${u_xcvr}/${txrx}_${phys_lane} ${a_jesd}/${txrx}_phy${n}
440	        } else {
441	          ad_connect  ${u_xcvr}/${txrx}_${phys_lane} ${a_jesd}/gt${n}_${txrx}
442	        }
443	      }
444	
445	      if {$tx_or_rx_n == 0} {
446	        if {$jesd204_type == 0} {
447	          if {$link_mode == 1} {
448	            ad_connect  ${a_jesd}/phy_en_char_align ${u_xcvr}/${txrx}_calign_${phys_lane}
449	          }
450	        } else {
451	          ad_connect  ${a_jesd}/rxencommaalign_out ${u_xcvr}/${txrx}_calign_${phys_lane}
452	        }
453	      }
454	    }
455	    if {$connect_empty_lanes == 1} {
456	      for {set n 0} {$n < $max_no_of_lanes} {incr n} {
457	
458	        set m [expr ($n + $index)]
459	
460	        if {$lane_map != {}} {
461	          set phys_lane [lindex $lane_map $n]
462	        } else {
463	          set phys_lane $m
464	        }
465	
466	        if {$tx_or_rx_n == 0} {
467	          ad_connect  ${a_xcvr}/up_es_${n} ${u_xcvr}/up_es_${phys_lane}
468	        }
469	
470	        if {(($n%4) == 0) && ($qpll_enable == 1)} {
471	          ad_connect  ${a_xcvr}/up_cm_${n} ${u_xcvr}/up_cm_${m}
472	        }
473	        ad_connect  ${a_xcvr}/up_ch_${n} ${u_xcvr}/up_${txrx}_${phys_lane}
474	        ad_connect  ${link_clk} ${u_xcvr}/${txrx}_clk_${phys_lane}
475	        if {$use_2x_clk == 1} {
476	          ad_connect  ${link_clk_2x} ${u_xcvr}/${txrx}_clk_2x_${phys_lane}
477	        }
478	
479	        create_bd_port -dir ${data_dir} ${m_data}_${m}_p
480	        create_bd_port -dir ${data_dir} ${m_data}_${m}_n
481	        ad_connect  ${u_xcvr}/${txrx}_${m}_p ${m_data}_${m}_p
482	        ad_connect  ${u_xcvr}/${txrx}_${m}_n ${m_data}_${m}_n
483	      }
484	    } else {
485	      ## Do nothing, the connections will be done manually
486	    }
487	
488	  } else {
489	    for {set n 0} {$n < $no_of_lanes} {incr n} {
490	
491	      set m [expr ($n + $index)]
492	      if {$lane_map != {}} {
493	        set phys_lane [lindex $lane_map $n]
494	      } else {
495	        set phys_lane $m
496	      }
497	
498	      if {$tx_or_rx_n == 0} {
499	        ad_connect  ${a_xcvr}/up_es_${n} ${u_xcvr}/up_es_${phys_lane}
500	        if {$jesd204_type == 0} {
501	          if {$link_mode == 1} {
502	            ad_connect  ${a_jesd}/phy_en_char_align ${u_xcvr}/${txrx}_calign_${phys_lane}
503	          }
504	        } else {
505	          ad_connect  ${a_jesd}/rxencommaalign_out ${u_xcvr}/${txrx}_calign_${phys_lane}
506	        }
507	      }
508	
509	      if {(($n%4) == 0) && ($qpll_enable == 1)} {
510	        ad_connect  ${a_xcvr}/up_cm_${n} ${u_xcvr}/up_cm_${m}
511	      }
512	      ad_connect  ${a_xcvr}/up_ch_${n} ${u_xcvr}/up_${txrx}_${phys_lane}
513	      ad_connect  ${link_clk} ${u_xcvr}/${txrx}_clk_${phys_lane}
514	      if {$use_2x_clk == 1} {
515	        ad_connect  ${link_clk_2x} ${u_xcvr}/${txrx}_clk_2x_${phys_lane}
516	      }
517	      if {$phys_lane != {}} {
518	        if {$jesd204_type == 0} {
519	          ad_connect  ${u_xcvr}/${txrx}_${phys_lane} ${a_jesd}/${txrx}_phy${n}
520	        } else {
521	          ad_connect  ${u_xcvr}/${txrx}_${phys_lane} ${a_jesd}/gt${n}_${txrx}
522	        }
523	      }
524	
525	      create_bd_port -dir ${data_dir} ${m_data}_${m}_p
526	      create_bd_port -dir ${data_dir} ${m_data}_${m}_n
527	      ad_connect  ${u_xcvr}/${txrx}_${m}_p ${m_data}_${m}_p
528	      ad_connect  ${u_xcvr}/${txrx}_${m}_n ${m_data}_${m}_n
529	    }
530	
531	    for {set n $no_of_lanes} {$n < $max_no_of_lanes} {incr n} {
532	
533	      set m [expr ($n + $index)]
534	
535	      if {$lane_map != {}} {
536	        set phys_lane [lindex $lane_map $n]
537	      } else {
538	        set phys_lane $m
539	      }
540	
541	      create_bd_port -dir ${data_dir} ${m_data}_${m}_p
542	      create_bd_port -dir ${data_dir} ${m_data}_${m}_n
543	      ad_connect  ${u_xcvr}/${txrx}_${m}_p ${m_data}_${m}_p
544	      ad_connect  ${u_xcvr}/${txrx}_${m}_n ${m_data}_${m}_n
545	      ad_connect  ${link_clk} ${u_xcvr}/${txrx}_clk_${phys_lane}
546	
547	      if {$tx_or_rx_n == 0} {
548	        if {$jesd204_type == 0} {
549	          if {$link_mode == 1} {
550		    ad_connect  ${a_jesd}/phy_en_char_align ${u_xcvr}/${txrx}_calign_${phys_lane}
551	          }
552		}
553	      }
554	    }
555	  }
556	
557	  if {$jesd204_type == 0} {
558	    ad_connect  ${a_jesd}/sysref $m_sysref
559	    if {$link_mode == 1} {
560	      ad_connect  ${a_jesd}/sync $m_sync
561	    }
562	    ad_connect  ${device_clk} ${a_jesd}/device_clk
563	    ad_connect  ${link_clk} ${a_jesd}/link_clk
564	  } else {
565	    ad_connect  ${a_jesd}/${txrx}_sysref $m_sysref
566	    ad_connect  ${a_jesd}/${txrx}_sync $m_sync
567	    ad_connect  ${device_clk} ${a_jesd}/${txrx}_core_clk
568	    ad_connect  ${a_xcvr}/up_status ${a_jesd}/${txrx}_reset_done
569	    ad_connect  ${rst_gen}/peripheral_reset ${a_jesd}/${txrx}_reset
570	  }
571	
572	  if {$tx_or_rx_n == 0} {
573	    set xcvr_rx_index [expr ($xcvr_rx_index + $max_no_of_lanes)]
574	  }
575	
576	  if {$tx_or_rx_n == 1} {
577	    set xcvr_tx_index [expr ($xcvr_tx_index + $max_no_of_lanes)]
578	  }
579	}
580	## Connect all the PLL clock and reset ports of the transceiver IP to a clock
