694	## Create an memory mapped interface connection to a MIG or PS7/8 IP, proc is
695	#  called in the ad_mem_hp[0|1|2|3]_interconnect processes, should never be
696	#  directly called in block designs.
697	#
698	#  \param[p_sel]  - name of the high speed interface, valid values are HP0, HP1
699	#  HP2, HP3, MEM in case of Microblaze, or SIM in case of simulation
700	#  \param[p_clk]  - name of the clock or reset source
701	#  \param[p_name] - name or list of names of the clock or reset sink
702	#
703	proc ad_mem_hpx_interconnect {p_sel p_clk p_name} {
704	
705	  global sys_zynq
706	  global sys_ddr_addr_seg
707	  global sys_hpc0_interconnect_index
708	  global sys_hpc1_interconnect_index
709	  global sys_hp0_interconnect_index
710	  global sys_hp1_interconnect_index
711	  global sys_hp2_interconnect_index
712	  global sys_hp3_interconnect_index
713	  global sys_mem_interconnect_index
714	  global sys_mem_clk_index
715	  global use_smartconnect
716	
717	  set p_name_int $p_name
718	  set p_clk_source [get_bd_pins -filter {DIR == O} -of_objects [get_bd_nets $p_clk]]
719	
720	  set connect_type "smartconnect"
721	  if {$use_smartconnect == 0} {
722	    set connect_type "axi_interconnect"
723	  }
724	
725	  if {$p_sel eq "SIM"} {
726	    if {$sys_mem_interconnect_index < 0} {
727	      ad_ip_instance $connect_type axi_mem_interconnect
728	    }
729	    set m_interconnect_index $sys_mem_interconnect_index
730	    set m_interconnect_cell [get_bd_cells axi_mem_interconnect]
731	    set m_addr_seg [get_bd_addr_segs -of_objects [get_bd_cells ddr_axi_vip]]
732	  }
733	
734	  if {$p_sel eq "MEM"} {
735	    if {$sys_mem_interconnect_index < 0} {
736	      ad_ip_instance $connect_type axi_mem_interconnect
737	    }
738	    set m_interconnect_index $sys_mem_interconnect_index
739	    set m_interconnect_cell [get_bd_cells axi_mem_interconnect]
740	    set m_addr_seg [get_bd_addr_segs -of_objects [get_bd_cells axi_ddr_cntrl] -filter "USAGE == memory"]
741	  }
742	
743	  if {($p_sel eq "HP0") && ($sys_zynq == 1)} {
744	    if {$sys_hp0_interconnect_index < 0} {
745	      set p_name_int sys_ps7/S_AXI_HP0
746	      set_property CONFIG.PCW_USE_S_AXI_HP0 {1} [get_bd_cells sys_ps7]
747	      ad_ip_instance $connect_type axi_hp0_interconnect
748	    }
749	    set m_interconnect_index $sys_hp0_interconnect_index
750	    set m_interconnect_cell [get_bd_cells axi_hp0_interconnect]
751	    set m_addr_seg [get_bd_addr_segs sys_ps7/S_AXI_HP0/HP0_DDR_LOWOCM]
752	  }
753	
754	  if {($p_sel eq "HP1") && ($sys_zynq == 1)} {
755	    if {$sys_hp1_interconnect_index < 0} {
756	      set p_name_int sys_ps7/S_AXI_HP1
757	      set_property CONFIG.PCW_USE_S_AXI_HP1 {1} [get_bd_cells sys_ps7]
758	      ad_ip_instance $connect_type axi_hp1_interconnect
759	    }
760	    set m_interconnect_index $sys_hp1_interconnect_index
761	    set m_interconnect_cell [get_bd_cells axi_hp1_interconnect]
762	    set m_addr_seg [get_bd_addr_segs sys_ps7/S_AXI_HP1/HP1_DDR_LOWOCM]
763	  }
764	
765	  if {($p_sel eq "HP2") && ($sys_zynq == 1)} {
766	    if {$sys_hp2_interconnect_index < 0} {
767	      set p_name_int sys_ps7/S_AXI_HP2
768	      set_property CONFIG.PCW_USE_S_AXI_HP2 {1} [get_bd_cells sys_ps7]
769	      ad_ip_instance $connect_type axi_hp2_interconnect
770	    }
771	    set m_interconnect_index $sys_hp2_interconnect_index
772	    set m_interconnect_cell [get_bd_cells axi_hp2_interconnect]
773	    set m_addr_seg [get_bd_addr_segs sys_ps7/S_AXI_HP2/HP2_DDR_LOWOCM]
774	  }
775	
776	  if {($p_sel eq "HP3") && ($sys_zynq == 1)} {
777	    if {$sys_hp3_interconnect_index < 0} {
778	      set p_name_int sys_ps7/S_AXI_HP3
779	      set_property CONFIG.PCW_USE_S_AXI_HP3 {1} [get_bd_cells sys_ps7]
780	      ad_ip_instance $connect_type axi_hp3_interconnect
781	    }
782	    set m_interconnect_index $sys_hp3_interconnect_index
783	    set m_interconnect_cell [get_bd_cells axi_hp3_interconnect]
784	    set m_addr_seg [get_bd_addr_segs sys_ps7/S_AXI_HP3/HP3_DDR_LOWOCM]
785	  }
786	
787	  if {($p_sel eq "HPC0") && ($sys_zynq == 2)} {
788	    if {$sys_hpc0_interconnect_index < 0} {
789	      set p_name_int sys_ps8/S_AXI_HPC0_FPD
790	      set_property CONFIG.PSU__USE__S_AXI_GP0 {1} [get_bd_cells sys_ps8]
791	      set_property CONFIG.PSU__AFI0_COHERENCY {1} [get_bd_cells sys_ps8]
792	      ad_ip_instance $connect_type axi_hpc0_interconnect
793	    }
794	    set m_interconnect_index $sys_hpc0_interconnect_index
795	    set m_interconnect_cell [get_bd_cells axi_hpc0_interconnect]
796	    set m_addr_seg [get_bd_addr_segs sys_ps8/SAXIGP0/HPC0_DDR_*]
797	  }
798	
799	  if {($p_sel eq "HPC1") && ($sys_zynq == 2)} {
800	    if {$sys_hpc1_interconnect_index < 0} {
801	      set p_name_int sys_ps8/S_AXI_HPC1_FPD
802	      set_property CONFIG.PSU__USE__S_AXI_GP1 {1} [get_bd_cells sys_ps8]
803	      set_property CONFIG.PSU__AFI1_COHERENCY {1} [get_bd_cells sys_ps8]
804	      ad_ip_instance $connect_type axi_hpc1_interconnect
805	    }
806	    set m_interconnect_index $sys_hpc1_interconnect_index
807	    set m_interconnect_cell [get_bd_cells axi_hpc1_interconnect]
808	    set m_addr_seg [get_bd_addr_segs sys_ps8/SAXIGP1/HPC1_DDR_*]
809	  }
810	
811	  if {($p_sel eq "HP0") && ($sys_zynq == 2)} {
812	    if {$sys_hp0_interconnect_index < 0} {
813	      set p_name_int sys_ps8/S_AXI_HP0_FPD
814	      set_property CONFIG.PSU__USE__S_AXI_GP2 {1} [get_bd_cells sys_ps8]
815	      ad_ip_instance $connect_type axi_hp0_interconnect
816	    }
817	    set m_interconnect_index $sys_hp0_interconnect_index
818	    set m_interconnect_cell [get_bd_cells axi_hp0_interconnect]
819	    set m_addr_seg [get_bd_addr_segs sys_ps8/SAXIGP2/HP0_DDR_*]
820	  }
821	
822	  if {($p_sel eq "HP1") && ($sys_zynq == 2)} {
823	    if {$sys_hp1_interconnect_index < 0} {
824	      set p_name_int sys_ps8/S_AXI_HP1_FPD
825	      set_property CONFIG.PSU__USE__S_AXI_GP3 {1} [get_bd_cells sys_ps8]
826	      ad_ip_instance $connect_type axi_hp1_interconnect
827	    }
828	    set m_interconnect_index $sys_hp1_interconnect_index
829	    set m_interconnect_cell [get_bd_cells axi_hp1_interconnect]
830	    set m_addr_seg [get_bd_addr_segs sys_ps8/SAXIGP3/HP1_DDR_*]
831	  }
832	
833	  if {($p_sel eq "HP2") && ($sys_zynq == 2)} {
834	    if {$sys_hp2_interconnect_index < 0} {
835	      set p_name_int sys_ps8/S_AXI_HP2_FPD
836	      set_property CONFIG.PSU__USE__S_AXI_GP4 {1} [get_bd_cells sys_ps8]
837	      ad_ip_instance $connect_type axi_hp2_interconnect
838	    }
839	    set m_interconnect_index $sys_hp2_interconnect_index
840	    set m_interconnect_cell [get_bd_cells axi_hp2_interconnect]
841	    set m_addr_seg [get_bd_addr_segs sys_ps8/SAXIGP4/HP2_DDR_*]
842	  }
843	
844	  if {($p_sel eq "HP3") && ($sys_zynq == 2)} {
845	    if {$sys_hp3_interconnect_index < 0} {
846	      set p_name_int sys_ps8/S_AXI_HP3_FPD
847	      set_property CONFIG.PSU__USE__S_AXI_GP5 {1} [get_bd_cells sys_ps8]
848	      ad_ip_instance $connect_type axi_hp3_interconnect
849	    }
850	    set m_interconnect_index $sys_hp3_interconnect_index
851	    set m_interconnect_cell [get_bd_cells axi_hp3_interconnect]
852	    set m_addr_seg [get_bd_addr_segs sys_ps8/SAXIGP5/HP3_DDR_*]
853	  }
854	
855	  if {$p_sel eq "NOC"} {
856	    set m_interconnect_index [get_property CONFIG.NUM_SI [get_bd_cells axi_noc_0]]
857	    set m_interconnect_cell [get_bd_cells axi_noc_0]
858	    set m_addr_seg [get_bd_addr_segs  axi_noc_0/S[format "%02s" [expr $m_interconnect_index +1]]_AXI/C0_DDR_LOW0]
859	    set sys_mem_clk_index [expr [get_property CONFIG.NUM_CLKS [get_bd_cells axi_noc_0]]-1]
860	  }
861	
862	  set i_str "S$m_interconnect_index"
863	  if {$m_interconnect_index < 10} {
864	    set i_str "S0$m_interconnect_index"
865	  }
866	
867	  set m_interconnect_index [expr $m_interconnect_index + 1]
868	
869	  set p_intf_name [lrange [split $p_name_int "/"] end end]
870	  set p_cell_name [lrange [split $p_name_int "/"] 0 0]
871	  set p_intf_clock [get_bd_pins -filter "TYPE == clk && (CONFIG.ASSOCIATED_BUSIF == ${p_intf_name} || \
872	    CONFIG.ASSOCIATED_BUSIF =~ ${p_intf_name}:* || CONFIG.ASSOCIATED_BUSIF =~ *:${p_intf_name} || \
873	    CONFIG.ASSOCIATED_BUSIF =~ *:${p_intf_name}:*)" -quiet -of_objects [get_bd_cells $p_cell_name]]
874	  if {[find_bd_objs -quiet -relation connected_to $p_intf_clock] ne "" ||
875	      $p_intf_clock eq $p_clk_source} {
876	    set p_intf_clock ""
877	  }
878	
879	  regsub clk $p_clk resetn p_rst
880	  if {[get_bd_nets -quiet $p_rst] eq ""} {
881	    set p_rst sys_cpu_resetn
882	  }
883	
884	  if {$m_interconnect_index == 0} {
885	    set_property CONFIG.NUM_MI 1 $m_interconnect_cell
886	    set_property CONFIG.NUM_SI 1 $m_interconnect_cell
887	    ad_connect $p_rst $m_interconnect_cell/ARESETN
888	    ad_connect $p_clk $m_interconnect_cell/ACLK
889	    ad_connect $m_interconnect_cell/M00_AXI $p_name_int
890	    if {$use_smartconnect == 0} {
891	      ad_connect $p_rst $m_interconnect_cell/M00_ARESETN
892	      ad_connect $p_clk $m_interconnect_cell/M00_ACLK
893	    }
894	    if {$p_intf_clock ne ""} {
895	      ad_connect $p_clk $p_intf_clock
896	    }
897	  } else {
898	
899	    set_property CONFIG.NUM_SI $m_interconnect_index $m_interconnect_cell
900	    if {$use_smartconnect == 1} {
901	      set clk_index [lsearch [get_bd_nets -of_object [get_bd_pins $m_interconnect_cell/ACLK*]] [get_bd_nets $p_clk]]
902	      if { $clk_index == -1 } {
903	          incr sys_mem_clk_index
904	          set_property CONFIG.NUM_CLKS [expr $sys_mem_clk_index +1] $m_interconnect_cell
905	          ad_connect $p_clk $m_interconnect_cell/ACLK$sys_mem_clk_index
906	          set asocc_clk_pin  $m_interconnect_cell/ACLK$sys_mem_clk_index
907	      } else {
908	        set asocc_clk_pin [lindex [get_bd_pins $m_interconnect_cell/ACLK*] $clk_index]
909	      }
910	    } else {
911	      ad_connect $p_rst $m_interconnect_cell/${i_str}_ARESETN
912	      ad_connect $p_clk $m_interconnect_cell/${i_str}_ACLK
913	    }
914	    ad_connect $m_interconnect_cell/${i_str}_AXI $p_name_int
915	    if {$p_intf_clock ne ""} {
916	      ad_connect $p_clk $p_intf_clock
917	    }
918	
919	    if {$p_sel eq "NOC"} {
920	      set_property -dict [list CONFIG.CONNECTIONS {MC_0 { read_bw {1720} write_bw {1720} read_avg_burst {4} write_avg_burst {4}} }] [get_bd_intf_pins /axi_noc_0/${i_str}_AXI]
921	      # Add the new bus as associated to the clock pin, append new if other exists
922	      set clk_asoc_port [get_property CONFIG.ASSOCIATED_BUSIF [get_bd_pins $asocc_clk_pin]]
923	      if {$clk_asoc_port != {}} {
924	       set clk_asoc_port ${clk_asoc_port}:
925	      }
926	      set_property -dict [list CONFIG.ASSOCIATED_BUSIF ${clk_asoc_port}${i_str}_AXI] [get_bd_pins $asocc_clk_pin]
927	    }
928	
929	    set mem_mapped ""
930	    if {$p_sel eq "MEM"} {
931	      # Search a DDR segment that is at least 16MB
932	      set mem_mapped [get_bd_addr_segs -of [get_bd_addr_spaces -of  [get_bd_intf_pins -filter {NAME=~ *DLMB*} -of [get_bd_cells /sys_mb]]] -regexp -filter {NAME=~ ".*ddr.*" && RANGE=~".*0{6}$"}]
933	    }
934	    if {$p_sel eq "SIM"} {
935	      set mem_mapped [get_bd_addr_segs -of [get_bd_addr_spaces -of  [get_bd_intf_pins -filter {NAME=~ *M_AXI*} -of [get_bd_cells /mng_axi_vip]]] -filter {NAME=~ *DDR* || NAME=~ *ddr*}]
936	    }
937	
938	    if {$mem_mapped eq ""} {
939	      assign_bd_address $m_addr_seg
940	    } else {
941	      assign_bd_address -offset [get_property OFFSET $mem_mapped] \
942	                        -range  [get_property RANGE $mem_mapped] $m_addr_seg
943	    }
944	  }
945	
946	  if {($use_smartconnect == 0) && ($m_interconnect_index > 1)} {
947	    set_property CONFIG.STRATEGY {2} $m_interconnect_cell
948	  }
949	
950	  if {$p_sel eq "SIM"} {set sys_mem_interconnect_index $m_interconnect_index}
951	  if {$p_sel eq "MEM"} {set sys_mem_interconnect_index $m_interconnect_index}
952	  if {$p_sel eq "HPC0"} {set sys_hpc0_interconnect_index $m_interconnect_index}
953	  if {$p_sel eq "HPC1"} {set sys_hpc1_interconnect_index $m_interconnect_index}
954	  if {$p_sel eq "HP0"} {set sys_hp0_interconnect_index $m_interconnect_index}
955	  if {$p_sel eq "HP1"} {set sys_hp1_interconnect_index $m_interconnect_index}
956	  if {$p_sel eq "HP2"} {set sys_hp2_interconnect_index $m_interconnect_index}
957	  if {$p_sel eq "HP3"} {set sys_hp3_interconnect_index $m_interconnect_index}
958	
959	}
960	
961	## Create an AXI4 Lite memory mapped interface connection for register maps,
962	#  instantiates an interconnect and reconfigure it at every process call.
963	#
964	#  \param[p_sel] - name of the high speed interface
965	#                  valid values are HPM0_FPD, HPM1_FPD, HPM0_LPD
966	#  \param[p_address] - address offset of the IP register map
967	#  \param[p_name] - name of the IP
968	#  \param[p_intf_name] - name of the AXI MM Slave interface (optional)
969	#
970	proc ad_hpmx_interconnect {p_sel p_address p_name {p_intf_name {}}} {
971	
972	  global sys_zynq
973	  global use_smartconnect
974	
975	  set interconnect_name [format "axi_%s_interconnect" [string tolower $p_sel]]
976	
977	  if {[catch {
978	    set interconnect_index [get_property CONFIG.NUM_MI [get_bd_cells $interconnect_name]]
979	  } err]} {
980	    set interconnect_index 0
981	  }
982	  set i_str [format "M%02d" $interconnect_index]
983	
984	  if {$i_str eq "M00"} {
985	
986	    if {$use_smartconnect == 1} {
987	      ad_ip_instance smartconnect $interconnect_name [ list \
988	        NUM_MI 1 \
989	        NUM_SI 1 \
990	      ]
991	      ad_connect sys_cpu_clk $interconnect_name/aclk
992	      ad_connect sys_cpu_resetn $interconnect_name/aresetn
993	    } else {
994	      ad_ip_instance axi_interconnect $interconnect_name
995	      ad_connect sys_cpu_clk $interconnect_name/ACLK
996	      ad_connect sys_cpu_clk $interconnect_name/S00_ACLK
997	      ad_connect sys_cpu_resetn $interconnect_name/ARESETN
998	      ad_connect sys_cpu_resetn $interconnect_name/S00_ARESETN
999	    }
1000	
1001	    if {$sys_zynq == 3} {
1002	      ad_connect sys_cpu_clk sys_cips/m_axi_fpd_aclk
1003	      ad_connect $interconnect_name/S00_AXI sys_cips/M_AXI_FPD
1004	    } elseif {($p_sel eq "HPM0_FPD") && ($sys_zynq == 2)} {
1005	      ad_connect sys_cpu_clk sys_ps8/maxihpm0_fpd_aclk
1006	      ad_connect $interconnect_name/S00_AXI sys_ps8/M_AXI_HPM0_FPD
1007	    } elseif {($p_sel eq "HPM1_FPD") && ($sys_zynq == 2)} {
1008	      ad_connect sys_cpu_clk sys_ps8/maxihpm1_fpd_aclk
1009	      ad_connect $interconnect_name/S00_AXI sys_ps8/M_AXI_HPM1_FPD
1010	    } elseif {($p_sel eq "HPM0_LPD") && ($sys_zynq == 2)} {
1011	      ad_connect sys_cpu_clk sys_ps8/maxihpm0_lpd_aclk
1012	      ad_connect $interconnect_name/S00_AXI sys_ps8/M_AXI_HPM0_LPD
1013	    } elseif {($p_sel eq "GP0") && ($sys_zynq == 1)} {
1014	      ad_connect sys_cpu_clk sys_ps7/M_AXI_GP0_ACLK
1015	      ad_connect $interconnect_name/S00_AXI sys_ps7/M_AXI_GP0
1016	    } elseif {($p_sel eq "GP1") && ($sys_zynq == 1)} {
1017	      ad_connect sys_cpu_clk sys_ps7/M_AXI_GP1_ACLK
1018	      ad_connect $interconnect_name/S00_AXI sys_ps7/M_AXI_GP1
1019	    } elseif {$sys_zynq == 0} {
1020	      ad_connect $interconnect_name/S00_AXI sys_mb/M_AXI_DP
1021	    } elseif {$sys_zynq == -1} {
1022	      ad_connect $interconnect_name/S00_AXI mng_axi_vip/M_AXI
1023	    }
1024	  }
1025	
1026	  if {$sys_zynq == 3} {
1027	    set sys_addr_cntrl_space [get_bd_addr_spaces /sys_cips/M_AXI_FPD]
1028	  }
1029	  if {$sys_zynq == 2} {
1030	    set sys_addr_cntrl_space [get_bd_addr_spaces sys_ps8/Data]
1031	  }
1032	  if {$sys_zynq == 1} {
1033	    set sys_addr_cntrl_space [get_bd_addr_spaces sys_ps7/Data]
1034	  }
1035	  if {$sys_zynq == 0} {
1036	    set sys_addr_cntrl_space [get_bd_addr_spaces sys_mb/Data]
1037	  }
1038	  if {$sys_zynq == -1} {
1039	    set sys_addr_cntrl_space [get_bd_addr_spaces mng_axi_vip/Master_AXI]
1040	  }
1041	
1042	  set interconnect_index [expr $interconnect_index + 1]
1043	
1044	  set p_cell [get_bd_cells $p_name]
1045	  set p_intf [get_bd_intf_pins -filter \
1046	    "MODE == Slave && VLNV == xilinx.com:interface:aximm_rtl:1.0 && NAME =~ *$p_intf_name*"\
1047	    -of_objects $p_cell]
1048	
1049	  set p_hier_cell $p_cell
1050	  set p_hier_intf $p_intf
1051	
1052	  while {$p_hier_intf != "" && [get_property TYPE $p_hier_cell] == "hier"} {
1053	    set p_hier_intf [find_bd_objs -boundary_type lower \
1054	      -relation connected_to $p_hier_intf]
1055	    if {$p_hier_intf != {}} {
1056	      set p_hier_cell [get_bd_cells -of_objects $p_hier_intf]
1057	    } else {
1058	      set p_hier_cell {}
1059	    }
1060	  }
1061	
1062	  set p_intf_clock ""
1063	  set p_intf_reset ""
1064	
1065	  if {$p_intf_name eq ""} {
1066	    set p_intf_name_bu ""
1067	  } else {
1068	    set p_intf_name_bu _${p_intf_name}
1069	  }
1070	
1071	  if {$p_hier_cell != {}} {
1072	    set p_intf_name [lrange [split $p_hier_intf "/"] end end]
1073	
1074	    set p_intf_clock [get_bd_pins -filter "TYPE == clk && \
1075	      (CONFIG.ASSOCIATED_BUSIF == ${p_intf_name} || \
1076	      CONFIG.ASSOCIATED_BUSIF =~ ${p_intf_name}:* || \
1077	      CONFIG.ASSOCIATED_BUSIF =~ *:${p_intf_name} || \
1078	      CONFIG.ASSOCIATED_BUSIF =~ *:${p_intf_name}:*)" \
1079	      -quiet -of_objects $p_hier_cell]
1080	    set p_intf_reset [get_bd_pins -filter "TYPE == rst && \
1081	      (CONFIG.ASSOCIATED_BUSIF == ${p_intf_name} || \
1082	       CONFIG.ASSOCIATED_BUSIF =~ ${p_intf_name}:* ||
1083	       CONFIG.ASSOCIATED_BUSIF =~ *:${p_intf_name} || \
1084	       CONFIG.ASSOCIATED_BUSIF =~ *:${p_intf_name}:*)" \
1085	       -quiet -of_objects $p_hier_cell]
1086	
1087	    if {($p_intf_clock ne "") && ($p_intf_reset eq "")} {
1088	      set p_intf_reset [get_property CONFIG.ASSOCIATED_RESET [get_bd_pins ${p_intf_clock}]]
1089	      if {$p_intf_reset ne ""} {
1090	        set p_intf_reset [get_bd_pins -filter "NAME == $p_intf_reset" -of_objects $p_hier_cell]
1091	      }
1092	    }
1093	
1094	    # Trace back up
1095	    set p_hier_cell2 $p_hier_cell
1096	
1097	    while {$p_intf_clock != {} && $p_hier_cell2 != $p_cell && $p_hier_cell2 != {}} {
1098	      puts $p_intf_clock
1099	      puts $p_hier_cell2
1100	      set p_intf_clock [find_bd_objs -boundary_type upper \
1101	        -relation connected_to $p_intf_clock]
1102	      if {$p_intf_clock != {}} {
1103	        set p_intf_clock [get_bd_pins [get_property PATH $p_intf_clock]]
1104	        set p_hier_cell2 [get_bd_cells -of_objects $p_intf_clock]
1105	      }
1106	    }
1107	
1108	    set p_hier_cell2 $p_hier_cell
1109	
1110	    while {$p_intf_reset != {} && $p_hier_cell2 != $p_cell && $p_hier_cell2 != {}} {
1111	      set p_intf_reset [find_bd_objs -boundary_type upper \
1112	        -relation connected_to $p_intf_reset]
1113	      if {$p_intf_reset != {}} {
1114	        set p_intf_reset [get_bd_pins [get_property PATH $p_intf_reset]]
1115	        set p_hier_cell2 [get_bd_cells -of_objects $p_intf_reset]
1116	      }
1117	    }
1118	  }
1119	
1120	
1121	  if {[find_bd_objs -quiet -relation connected_to $p_intf_clock] ne ""} {
1122	    set p_intf_clock ""
1123	  }
1124	  if {$p_intf_reset ne ""} {
1125	    if {[find_bd_objs -quiet -relation connected_to $p_intf_reset] ne ""} {
1126	      set p_intf_reset ""
1127	    }
1128	  }
1129	
1130	  set_property CONFIG.NUM_MI $interconnect_index [get_bd_cells $interconnect_name]
1131	
1132	  if {$use_smartconnect == 0} {
1133	    ad_connect sys_cpu_clk $interconnect_name/${i_str}_ACLK
1134	    ad_connect sys_cpu_resetn $interconnect_name/${i_str}_ARESETN
1135	  }
1136	  if {$p_intf_clock ne ""} {
1137	    ad_connect sys_cpu_clk ${p_intf_clock}
1138	  }
1139	  if {$p_intf_reset ne ""} {
1140	    ad_connect sys_cpu_resetn ${p_intf_reset}
1141	  }
1142	  ad_connect $interconnect_name/${i_str}_AXI ${p_intf}
1143	
1144	  set p_seg [get_bd_addr_segs -of [get_bd_addr_spaces -of [get_bd_intf_pins -filter "NAME=~ *${p_intf_name}*" -of $p_hier_cell]]]
1145	  set p_index 0
1146	  foreach p_seg_name $p_seg {
1147	    if {$p_index == 0} {
1148	      set p_seg_range [get_property range $p_seg_name]
1149	      if {$p_seg_range < 0x1000} {
1150	        set p_seg_range 0x1000
1151	      }
1152	      if {$sys_zynq == 3} {
1153	        if {($p_address >= 0x44000000) && ($p_address <= 0x4fffffff)} {
1154	          # place axi peripherics in A400_0000-AFFF_FFFF range
1155	          set p_address [expr ($p_address + 0x60000000)]
1156	        } elseif {($p_address >= 0x70000000) && ($p_address <= 0x7fffffff)} {
1157	          # place axi peripherics in B000_0000-BFFF_FFFF range
1158	          set p_address [expr ($p_address + 0x40000000)]
1159	        } else {
1160	          error "ERROR: ad_cpu_interconnect : Cannot map ($p_address) to aperture, \
1161	                Addess out of range 0x4400_0000 - 0X4FFF_FFFF; 0x7000_0000 - 0X7FFF_FFFF !"
1162	        }
1163	      }
1164	      if {$sys_zynq == 2} {
1165	        if {($p_address >= 0x40000000) && ($p_address <= 0x4fffffff)} {
1166	          set p_address [expr ($p_address + 0x40000000)]
1167	        }
1168	        if {($p_address >= 0x70000000) && ($p_address <= 0x7fffffff)} {
1169	          set p_address [expr ($p_address + 0x20000000)]
1170	        }
1171	      }
1172	      puts "create_bd_addr_seg -range $p_seg_range -offset $p_address $sys_addr_cntrl_space $p_seg_name SEG_data_${p_name}${p_intf_name_bu}"
1173	      create_bd_addr_seg -range $p_seg_range \
1174	        -offset $p_address $sys_addr_cntrl_space \
1175	        $p_seg_name "SEG_data_${p_name}${p_intf_name_bu}"
1176	    } else {
1177	      assign_bd_address $p_seg_name
1178	    }
1179	    incr p_index
1180	  }
1181	}
1182	
1183	## Create an AXI4 Lite memory mapped interface connection for register maps,
1184	#  instantiates an interconnect and reconfigure it at every process call.
1185	#
1186	#  \param[p_address] - address offset of the IP register map
1187	#  \param[p_name] - name of the IP
1188	#  \param[p_intf_name] - name of the AXI MM Slave interface (optional)
1189	#
1190	proc ad_cpu_interconnect {p_address p_name {p_intf_name {}}} {
1191	
1192	  global sys_zynq
1193	
1194	  if {$sys_zynq == -1} {
1195	    ad_hpmx_interconnect "AXI"      $p_address $p_name $p_intf_name
1196	  } elseif {$sys_zynq ==  0} {
1197	    ad_hpmx_interconnect "DP"       $p_address $p_name $p_intf_name
1198	  } elseif {$sys_zynq ==  1} {
1199	    ad_hpmx_interconnect "GP0"      $p_address $p_name $p_intf_name
1200	  } elseif {$sys_zynq ==  2} {
1201	    ad_hpmx_interconnect "HPM0_LPD" $p_address $p_name $p_intf_name
1202	  } elseif {$sys_zynq ==  3} {
1203	    ad_hpmx_interconnect "FPD"      $p_address $p_name $p_intf_name
1204	  }
1205	}
1206	
1207	## Connects an IP interrupt port to the system's interrupt controller interface.
1208	#
1209	#  \param[p_ps_index] - interrupt index used in PSx based architecture
1210	#  \param[p_mb_index] - interrupt index used in Microblaze based architecture
1211	#  \param[p_name] - name of the interrupt port
1212	#
1213	proc ad_cpu_interrupt {p_ps_index p_mb_index p_name} {
1214	
1215	  global sys_zynq
1216	
1217	  if {$sys_zynq <= 0} {set p_index_int $p_mb_index}
1218	  if {$sys_zynq >= 1} {set p_index_int $p_ps_index}
1219	
1220	  set p_index [regsub -all {[^0-9]} $p_index_int ""]
1221	  set m_index [expr ($p_index - 8)]
1222	
1223	  if {$sys_zynq == 3} {
1224	   if {$p_index < 0 || $p_index > 15} {
1225	      error "ERROR: ad_cpu_interrupt : Interrupt index ($p_index) out of range 0-15 "
1226	    }
1227	    ad_connect $p_name sys_cips/pl_ps_irq$p_index
1228	  }
1229	
1230	  if {($sys_zynq == 2) && ($p_index <= 7)} {
1231	    set p_net [get_bd_nets -of_objects [get_bd_pins sys_concat_intc_0/In$p_index]]
1232	    set p_pin [get_bd_pins sys_concat_intc_0/In$p_index]
1233	
1234	    puts "disconnect_bd_net $p_net $p_pin"
1235	    disconnect_bd_net $p_net $p_pin
1236	    ad_connect sys_concat_intc_0/In$p_index $p_name
1237	  }
1238	
1239	  if {($sys_zynq == 2) && ($p_index >= 8)} {
1240	    set p_net [get_bd_nets -of_objects [get_bd_pins sys_concat_intc_1/In$m_index]]
1241	    set p_pin [get_bd_pins sys_concat_intc_1/In$m_index]
1242	
1243	    puts "disconnect_bd_net $p_net $p_pin"
1244	    disconnect_bd_net $p_net $p_pin
1245	    ad_connect sys_concat_intc_1/In$m_index $p_name
1246	  }
1247	
1248	  if {$sys_zynq <= 1} {
1249	
1250	    set p_net [get_bd_nets -of_objects [get_bd_pins sys_concat_intc/In$p_index]]
1251	    set p_pin [get_bd_pins sys_concat_intc/In$p_index]
1252	
1253	    puts "disconnect_bd_net $p_net $p_pin"
